INSERT INTO feature VALUES('spinal-duplication','conversion','Spinal duplication in the conversion engine','engine-sharing','partial','uncommon','dependent provers','Duplicating a shared abstraction under the spinal stance copies its spine, the paths from its binder to the binder''s occurrences, and shares each rib, a maximal subterm of its body that does not read the binder, so a rib is evaluated once across every application, and the duplicate erases to the term the copying stance evaluates. The stance is admitted on a property over generated roots: a spinal run reads back as the copying stance''s run, or refuses as it does. Under the spinal granularity stance the conversion machine mints a channel per prefix of a spine, so a partial application two unfoldings share is evaluated once. Both shared evaluations run only through a sink that records the conversion trace, and no checker path installs either.','core-nbe','crates/core-nbe/tests/full_laziness.rs crates/core-nbe/tests/duplication.rs crates/core-nbe/src/machine/tests.rs corpus/ledger/features/spinal-duplication.gandr','corpus/ledger/features/spinal-duplication.gandr','#2801');
